func composeDirection(medium, mood, palette string) string {
	parts := make([]string, 0, 3)
	// Palette FIRST (2026-07-20, bugs_open/027 4b): the composed direction is
	// truncated at maxImageryDirectionInPrompt and the palette is both the
	// shortest field and the one carrying brand identity, so it must not be
	// the tail. A verbose medium+mood previously evicted the colours entirely
	// and the model invented an accent -- silently, and the image looked
	// deliberate. medium/mood are prose and degrade gracefully when clipped.
	if palette != "" {
		parts = append(parts, "colour palette: "+palette)
	}
	if medium != "" {
		parts = append(parts, medium)
	}
	if mood != "" {
		parts = append(parts, mood)
	}
	return strings.Join(parts, ". ")
}

// generate_image_actions.go:1138-1151, composeImagePromptWithDirection
if len(direction) > maxImageryDirectionInPrompt {
	// Rune-safe cut (edit 4); the backoff below then sees a valid string.
	cut := datahelpers.SafeCut(direction, maxImageryDirectionInPrompt)
	minKeep := maxImageryDirectionInPrompt / 2
	// LAST sentence boundary within the cap, not the first (bugs_open/027,
	// round 5): with a long leading clause (palette-first composition), the
	// first '. ' past minKeep is the end of that clause, and cutting there
	// discards later clauses that fit. LastIndex keeps every complete
	// sentence that fits.
	if idx := strings.LastIndex(cut, ". "); idx > minKeep {
		cut = cut[:idx+1]
	} else if idx := strings.LastIndex(cut, ", "); idx > minKeep {
		cut = cut[:idx]
	}
	direction = strings.TrimSpace(cut)
}

