func TestComposeImagePromptWithDirectionKeepsPaletteAndMedium(t *testing.T) {
	// robot-hands.com content_hero, verbatim: palette clause 122 chars (> minKeep),
	// full direction 233 (> cap). Under first-sentence backoff this kept ONLY
	// the palette; last-sentence keeps palette + medium.
	g := &imageryStyleGuide{Kinds: map[string]imageryStyleGuideKindOverride{
		"content_hero": {
			Medium:  "flat duotone editorial illustration",
			Mood:    "bold simple silhouette of the subject, minimal detail, precise, technical",
			Palette: "deep charcoal ground, electric blue (#0080FF) flat shapes and linework, light grey secondary accents only",
		},
	}}
	direction := g.directionForKind("content_hero")
	if len(direction) <= maxImageryDirectionInPrompt {
		t.Fatalf("fixture must exceed the cap; got %d", len(direction))
	}
	got := composeImagePromptWithDirection("Article header image for a robotics guide", direction)
	for _, want := range []string{"#0080FF", "accents only", "flat duotone editorial illustration", "Article header image for a robotics guide"} {
		if !strings.Contains(got, want) {
			t.Errorf("lost %q from the composed prompt.\ngot: %q", want, got)
		}
	}
}

func TestSafeCutIsRuneSafe(t *testing.T) {
	s := strings.Repeat("a", 199) + "\u2019tail" // curly quote straddles the cap
	if got := datahelpers.SafeCut(s, 200); !utf8.ValidString(got) {
		t.Errorf("SafeCut produced invalid UTF-8: %q", got)
	}
}

// SafeCut returns at most n BYTES of s, never splitting a multi-byte rune.
// The one truncation primitive in this package: TruncateString is expressed
// in terms of it, and callers needing a cut WITHOUT an ellipsis (e.g. image
// prompt composition, where '...' would be read by the model as an
// instruction) use it directly.
func SafeCut(s string, n int) string {
	if n <= 0 {
		return ""
	}
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

func TruncateString(s string, maxLength int) string {
	if len(s) <= maxLength {
		return s
	}
	// was: s[:maxLength] + "..." — split multi-byte runes and emitted
	// invalid UTF-8 into logs and prompt previews.
	return SafeCut(s, maxLength) + "..."
}
